//! Rusticol reports and admits the pyamplicol (PyPI) version, `<MG>.<N>`,
//! which Cargo's semver cannot carry. The wheel build passes it as
//! PYAMPLICOL_PACKAGE_VERSION; a plain `cargo build`/`cargo test` reads it
//! from pyproject.toml, so artifacts generated by Python still load.

use std::env;
use std::fs;
use std::path::PathBuf;

fn project_version(text: &str) -> Option<&str> {
    let mut in_project = false;
    for line in text.lines() {
        let line = line.trim();
        if line.starts_with('[') {
            in_project = line == "[project]";
        } else if in_project && let Some(value) = line.strip_prefix("version") {
            let value = value.trim_start().strip_prefix('=')?.trim();
            return value.strip_prefix('"')?.strip_suffix('"');
        }
    }
    None
}

fn main() {
    println!("cargo:rerun-if-env-changed=PYAMPLICOL_PACKAGE_VERSION");
    if env::var_os("PYAMPLICOL_PACKAGE_VERSION").is_some() {
        return;
    }
    let manifest = PathBuf::from(env::var_os("CARGO_MANIFEST_DIR").expect("CARGO_MANIFEST_DIR"));
    let pyproject = manifest.join("../../../pyproject.toml");
    println!("cargo:rerun-if-changed={}", pyproject.display());
    if let Some(version) = fs::read_to_string(&pyproject)
        .ok()
        .as_deref()
        .and_then(project_version)
    {
        println!("cargo:rustc-env=PYAMPLICOL_PACKAGE_VERSION={version}");
    }
}
